import React, { useState, useEffect, useRef } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';
import { useSwipeable } from 'react-swipeable';

// Set up PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const PDFViewer = ({ pdfPath, bookTitle }) => {
  const { theme } = useTheme();
  const [pdf, setPdf] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [scale, setScale] = useState(1.2);
  const [error, setError] = useState(null);
  const [pageDirection, setPageDirection] = useState(0);
  const [pageUrls, setPageUrls] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [showPlaceholder, setShowPlaceholder] = useState(false);
  const containerRef = useRef(null);
  
  // Function to render a page to the cache
  const renderPageToCache = async (pdfDoc, pageNum, cache) => {
    if (!pdfDoc) return null;
    
    const page = await pdfDoc.getPage(pageNum);
    const viewport = page.getViewport({ scale: 1.0 });
    
    // Create an offscreen canvas
    const canvas = document.createElement('canvas');
    canvas.height = viewport.height;
    canvas.width = viewport.width;
    
    // Render to the canvas
    const renderContext = {
      canvasContext: canvas.getContext('2d'),
      viewport: viewport
    };
    
    await page.render(renderContext).promise;
    
    // Store the rendered page as a data URL
    const pageUrl = canvas.toDataURL('image/png');
    cache[pageNum] = pageUrl;
    
    return pageUrl;
  };
  
  // Load the PDF document
  useEffect(() => {
    let loadingTask = null;
    let isMounted = true;
    
    async function loadPDF() {
      try {
        setError(null);
        setIsLoading(true);
        setShowPlaceholder(false);
        
        // Handle case when pdfPath is not provided
        if (!pdfPath) {
          if (isMounted) {
            setShowPlaceholder(true);
            setError("No PDF document specified");
            setIsLoading(false);
          }
          return;
        }
        
        // Load the PDF
        loadingTask = pdfjsLib.getDocument(pdfPath);
        const loadedPdf = await loadingTask.promise;
        
        if (!isMounted) return;
        
        setPdf(loadedPdf);
        setTotalPages(loadedPdf.numPages);
        setCurrentPage(1);
        
        // Pre-render the first 3 pages for smooth transitions
        if (loadedPdf.numPages > 0) {
          const pageCache = {};
          
          // Render first page
          await renderPageToCache(loadedPdf, 1, pageCache);
          
          // Render second page if it exists
          if (loadedPdf.numPages > 1) {
            await renderPageToCache(loadedPdf, 2, pageCache);
          }
          
          if (isMounted) {
            setPageUrls(pageCache);
            setIsLoading(false);
          }
        }
      } catch (err) {
        if (isMounted) {
          console.error('Error loading PDF:', err);
          setError(`Failed to load PDF: ${err.message}`);
          setIsLoading(false);
        }
      }
    }
    
    loadPDF();
    
    return () => {
      isMounted = false;
      if (loadingTask) {
        loadingTask.destroy().catch(err => console.error('Error destroying PDF task:', err));
      }
    };
  }, [pdfPath]);
  
  // Preload the next page when needed
  useEffect(() => {
    if (!pdf || !currentPage) return;
    
    async function preloadAdjacentPages() {
      // Preload next page
      if (currentPage < totalPages && !pageUrls[currentPage + 1]) {
        await renderPageToCache(pdf, currentPage + 1, {...pageUrls});
        setPageUrls(prev => ({...prev}));
      }
      
      // Preload previous page
      if (currentPage > 1 && !pageUrls[currentPage - 1]) {
        await renderPageToCache(pdf, currentPage - 1, {...pageUrls});
        setPageUrls(prev => ({...prev}));
      }
    }
    
    preloadAdjacentPages();
  }, [pdf, currentPage, totalPages, pageUrls]);
  
  // Functions for page and zoom control
  const changePage = (delta) => {
    const newPage = currentPage + delta;
    if (newPage >= 1 && newPage <= totalPages) {
      setPageDirection(delta);
      setCurrentPage(newPage);
    }
  };
  
  const changeZoom = (delta) => {
    const newScale = Math.max(0.5, Math.min(3, scale + delta));
    setScale(newScale);
  };
  
  // Page flip animation variants
  const pageVariants = {
    enter: (direction) => ({
      x: direction > 0 ? "100%" : "-100%",
      opacity: 0,
      rotateY: direction > 0 ? -20 : 20,
      boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
    }),
    center: {
      x: 0,
      opacity: 1,
      rotateY: 0,
      boxShadow: "0px 10px 30px rgba(0, 0, 0, 0.3)"
    },
    exit: (direction) => ({
      x: direction < 0 ? "100%" : "-100%",
      opacity: 0,
      rotateY: direction < 0 ? -20 : 20,
      boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
    })
  };
  
  // Handle swipe gestures
  const swipeHandlers = useSwipeable({
    onSwipedLeft: () => changePage(1),
    onSwipedRight: () => changePage(-1),
    preventDefaultTouchmoveEvent: true,
    trackMouse: false,
    trackTouch: true,
    delta: 10, // Lower threshold for swipe detection
    swipeDuration: 500, // Allow slower swipes
  });

  // Handle keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'ArrowRight') {
        changePage(1);
      } else if (e.key === 'ArrowLeft') {
        changePage(-1);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentPage, totalPages, changePage]);
  
  // Resize handling for responsiveness
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const containerWidth = containerRef.current.clientWidth;
        const containerHeight = containerRef.current.clientHeight;
        // More responsive scaling based on both dimensions
        const isMobile = window.innerWidth < 768;
        // Use smaller scale on mobile for better fit
        const newScale = isMobile 
          ? Math.min(0.9, (containerWidth / 600) * 0.9, (containerHeight / 800) * 0.9) 
          : Math.min(1.2, containerWidth / 600);
        setScale(newScale);
      }
    };
    
    handleResize(); // Call once to initialize
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Add touch gesture handling for pinch zoom
  useEffect(() => {
    if (!containerRef.current) return;
    
    let initialDistance = 0;
    let initialScale = scale;
    
    const handleTouchStart = (e) => {
      if (e.touches.length === 2) {
        // Get initial distance between two fingers
        initialDistance = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        initialScale = scale;
      }
    };
    
    const handleTouchMove = (e) => {
      if (e.touches.length === 2) {
        // Calculate new distance
        const newDistance = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        
        // Calculate scale factor based on distance change
        const scaleFactor = newDistance / initialDistance;
        const newScale = Math.max(0.5, Math.min(3, initialScale * scaleFactor));
        
        setScale(newScale);
        e.preventDefault(); // Prevent default pinch zoom
      }
    };
    
    const container = containerRef.current;
    container.addEventListener('touchstart', handleTouchStart, { passive: false });
    container.addEventListener('touchmove', handleTouchMove, { passive: false });
    
    return () => {
      container.removeEventListener('touchstart', handleTouchStart);
      container.removeEventListener('touchmove', handleTouchMove);
    };
  }, [scale]);

  // Render placeholder when no PDF is specified
  if (showPlaceholder) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center">
        <div className="p-3 bg-blue-500/10 rounded-full inline-block mb-4 border border-blue-500/30">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
          </svg>
        </div>
        <h2 className={`text-xl font-semibold mb-2 ${theme.text.primary}`}>
          No document selected
        </h2>
        <p className={`${theme.text.secondary} max-w-lg`}>
          Please select a book from your library to view its contents here.
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header with controls - make more touch-friendly on mobile */}
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-3 md:mb-5 gap-2">
        <h3 className={`text-lg font-medium ${theme.text.primary} truncate max-w-full md:max-w-xs pl-2 border-l-2 border-blue-500/30`}>
          {bookTitle || 'PDF Viewer'}
        </h3>
        
        <div className="flex items-center self-end px-2 py-1 rounded-xl bg-gray-800/50 backdrop-blur-sm border border-gray-700/30">
          {/* Page Controls - Larger touch targets */}
          <div className="flex items-center mr-3">
            <motion.button
              className="p-3 bg-gray-700/50 rounded-lg hover:bg-gray-600/50 transition-colors mr-2"
              whileTap={{ scale: 0.9 }}
              onClick={() => changePage(-1)}
              disabled={currentPage <= 1}
              aria-label="Previous page"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
              </svg>
            </motion.button>
            
            <span className={`text-sm ${theme.text.secondary} bg-gray-800/70 px-2 py-1 rounded-md min-w-[60px] text-center`}>
              {currentPage} / {totalPages}
            </span>
            
            <motion.button
              className="p-3 bg-gray-700/50 rounded-lg hover:bg-gray-600/50 transition-colors ml-2"
              whileTap={{ scale: 0.9 }}
              onClick={() => changePage(1)}
              disabled={currentPage >= totalPages}
              aria-label="Next page"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
              </svg>
            </motion.button>
          </div>
          
          {/* Zoom Controls - Larger touch targets */}
          <div className="flex items-center border-l border-gray-700/30 pl-3">
            <motion.button
              className="p-3 bg-gray-700/50 rounded-lg hover:bg-gray-600/50 transition-colors mr-2"
              whileTap={{ scale: 0.9 }}
              onClick={() => changeZoom(-0.1)}
              aria-label="Zoom out"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" />
              </svg>
            </motion.button>
            
            <span className={`text-sm ${theme.text.secondary} bg-gray-800/70 px-2 py-1 rounded-md min-w-[60px] text-center`}>
              {Math.round(scale * 100)}%
            </span>
            
            <motion.button
              className="p-3 bg-gray-700/50 rounded-lg hover:bg-gray-600/50 transition-colors ml-2"
              whileTap={{ scale: 0.9 }}
              onClick={() => changeZoom(0.1)}
              aria-label="Zoom in"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
              </svg>
            </motion.button>
          </div>
        </div>
      </div>
      
      {/* PDF Viewer Container - Improved for mobile */}
      <div 
        ref={containerRef}
        className="relative flex-grow overflow-auto rounded-xl bg-gray-800/50 touch-pan-y border border-gray-700/30 shadow-inner"
        style={{ perspectiveOrigin: "center", perspective: "1200px" }}
        {...swipeHandlers}
      >
        <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 to-indigo-600/5 -z-10"></div>
        
        {/* Guide overlay for touch gestures on mobile (shown initially) */}
        {isLoading && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-900/80 z-30 touch-none">
            <div className="text-center p-6 bg-gray-800/90 rounded-xl max-w-xs border border-gray-700/30">
              <div className="flex justify-center mb-4">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 11.5V14m0-2.5v-6a1.5 1.5 0 113 0m-3 6a1.5 1.5 0 00-3 0v2a7.5 7.5 0 0015 0v-5a1.5 1.5 0 00-3 0m-6-3V11m0-5.5v-1a1.5 1.5 0 013 0v1m0 0V11m0-5.5a1.5 1.5 0 013 0v3m0 0V11" />
                </svg>
              </div>
              <p className="text-white text-lg font-medium mb-2">Touch Controls:</p>
              <ul className="text-sm text-gray-300 space-y-2 text-left">
                <li className="flex items-center">
                  <span className="mr-2">👆</span> Swipe left/right to turn pages
                </li>
                <li className="flex items-center">
                  <span className="mr-2">👌</span> Pinch to zoom in and out
                </li>
              </ul>
            </div>
          </div>
        )}
        
        {error ? (
          <div className="flex items-center justify-center h-full p-4">
            <div className="text-center">
              <div className="p-3 bg-red-500/10 rounded-full inline-block mb-4 border border-red-500/30">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <p className="mb-3 text-lg font-semibold text-red-400">Error loading PDF</p>
              <p className={`${theme.text.secondary} mb-4`}>{error}</p>
              <motion.button 
                className="px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-700 text-white rounded-xl shadow-lg border border-blue-500/30 relative overflow-hidden group"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => window.location.reload()}
              >
                <div className="absolute inset-0 bg-gradient-to-r from-blue-400/20 to-indigo-400/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                <span className="font-medium">Try Again</span>
              </motion.button>
            </div>
          </div>
        ) : (
          <AnimatePresence initial={false} mode="wait">
            <motion.div 
              key={currentPage}
              custom={pageDirection}
              variants={pageVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{
                x: { type: "spring", stiffness: 300, damping: 30 },
                opacity: { duration: 0.2 }
              }}
              className="flex justify-center min-h-full py-4 px-2"
            >
              {isLoading && !pageUrls[currentPage] ? (
                <div className="flex items-center justify-center w-full">
                  <div className="relative w-16 h-16">
                    <div className="absolute inset-0 rounded-full border-4 border-blue-500/30 opacity-75"></div>
                    <div className="absolute inset-0 rounded-full border-4 border-transparent border-t-blue-500 animate-spin"></div>
                  </div>
                </div>
              ) : (
                <div>
                  {pageUrls[currentPage] && (
                    <img 
                      src={pageUrls[currentPage]} 
                      alt={`Page ${currentPage}`} 
                      style={{ 
                        transform: `scale(${scale})`,
                        transformOrigin: "top center", 
                        maxWidth: "100%",
                        transition: "transform 0.2s ease" 
                      }}
                      className="shadow-xl rounded"
                    />
                  )}
                </div>
              )}
            </motion.div>
          </AnimatePresence>
        )}
      </div>
      
      {/* Mobile page navigation indicators */}
      <div className="md:hidden flex justify-center mt-4 space-x-1">
        <div className="flex items-center bg-gray-800/50 px-3 py-1.5 rounded-full border border-gray-700/30">
          <motion.button
            whileTap={{ scale: 0.9 }}
            onClick={() => changePage(-1)}
            disabled={currentPage <= 1}
            className="mr-2 opacity-80"
            aria-label="Previous page"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </motion.button>
          
          <div className="text-sm text-center text-white">
            Page <span className="font-medium text-blue-400">{currentPage}</span> of {totalPages}
          </div>
          
          <motion.button
            whileTap={{ scale: 0.9 }}
            onClick={() => changePage(1)}
            disabled={currentPage >= totalPages}
            className="ml-2 opacity-80"
            aria-label="Next page"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </motion.button>
        </div>
      </div>
    </div>
  );
};

export default PDFViewer; 