import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import PDFThumbnail from './PDFThumbnail';
import { useTheme } from '../contexts/ThemeContext';

const BookListWithThumbnails = ({ searchQuery = '', onSelectBook, categoryFilter = null }) => {
  const { theme } = useTheme();
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [categories, setCategories] = useState([]);

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: (i) => ({
      opacity: 1,
      y: 0,
      transition: {
        delay: i * 0.1,
        duration: 0.3,
        ease: "easeInOut"
      }
    })
  };

  // Load books from index.json and add real PDF files
  useEffect(() => {
    let isMounted = true;
    
    async function loadBooks() {
      try {
        setLoading(true);
        setError(null);
        
        // Use hardcoded book data
        const bookData = [
          {
            "id": "simple-test",
            "title": "Simple Test PDF",
            "filename": "Simple_Test.pdf",
            "author": "Track Your Study Team",
            "description": "A simple test PDF file",
            "category": "Test",
            "addedDate": "2023-09-30"
          },
          {
            "id": "test-thumbnail",
            "title": "Test Thumbnail PDF",
            "filename": "test_thumbnail.pdf",
            "author": "Track Your Study Team",
            "description": "A test PDF for thumbnail generation",
            "category": "Test",
            "addedDate": "2023-09-30"
          },
          {
            "id": "personal-jokes",
            "title": "Personal Jokes in Aristophanes",
            "filename": "Personal Jokes in Aristophanes FS Halliwell, Worcester College D Phil The material of this thesis - PDF Room.pdf",
            "author": "FS Halliwell, Worcester College",
            "description": "A thesis on Personal Jokes in Aristophanes",
            "category": "Academic",
            "addedDate": "2023-09-30"
          },
          {
            "id": "yo-mama-jokes",
            "title": "Yo Mama Jokes Encyclopedia",
            "filename": "Yo Mama Jokes EncyclopediaThe Worlds Funniest Yo Momma Jokes! - PDF Room.pdf",
            "author": "PDF Room",
            "description": "The Worlds Funniest Yo Momma Jokes!",
            "category": "Humor",
            "addedDate": "2023-09-30"
          },
          {
            "id": "batman-killing-joke",
            "title": "Batman: The Killing Joke",
            "filename": "Batman_ The Killing Joke - PDF Room.pdf",
            "author": "DC Comics",
            "description": "A famous Batman graphic novel",
            "category": "Comics",
            "addedDate": "2023-09-30"
          }
        ];
        
        // Extract unique categories
        const uniqueCategories = Array.from(new Set(bookData
          .filter(book => book.category)
          .map(book => book.category)));
        
        if (isMounted) {
          setBooks(bookData.map(book => ({
            ...book,
            path: `${process.env.PUBLIC_URL}/books/${book.filename}`,
            progress: book.progress || Math.floor(Math.random() * 100)
          })));
          setCategories(uniqueCategories);
          setLoading(false);
        }
      } catch (err) {
        console.error('Error loading books:', err);
        if (isMounted) {
          setError(err.message);
          setLoading(false);
        }
      }
    }
    
    loadBooks();
    
    return () => {
      isMounted = false;
    };
  }, []);
  
  // Filter books based on search query and category
  const filteredBooks = useMemo(() => {
    return books.filter(book => {
      const matchesSearch = !searchQuery || 
        book.title?.toLowerCase().includes((searchQuery || '').toLowerCase()) ||
        book.author?.toLowerCase().includes((searchQuery || '').toLowerCase()) ||
        book.description?.toLowerCase().includes((searchQuery || '').toLowerCase());
      
      const matchesCategory = !categoryFilter || book.category === categoryFilter;
      
      return matchesSearch && matchesCategory;
    });
  }, [books, searchQuery, categoryFilter]);
  
  const handleBookClick = (book) => {
    try {
      // Verify the PDF exists before attempting to open it
      fetch(book.path, { method: 'HEAD' })
        .then(response => {
          if (!response.ok) {
            throw new Error(`PDF file not found: ${book.path}`);
          }
          if (onSelectBook) {
            onSelectBook(book);
          }
        })
        .catch(err => {
          console.error('Error verifying PDF:', err);
          // Show error state in the UI rather than throwing
          setError(`Failed to open "${book.title}". The PDF file may be missing.`);
          setTimeout(() => setError(null), 3000); // Clear error after 3 seconds
        });
    } catch (err) {
      console.error('Error handling book click:', err);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="flex flex-col items-center">
          <div className="w-16 h-16 relative mb-4">
            <div className="absolute inset-0 rounded-full border-4 border-blue-500/30 opacity-75"></div>
            <div className="absolute inset-0 rounded-full border-4 border-transparent border-t-blue-500 animate-spin"></div>
          </div>
          <p className={`${theme.text.secondary} font-medium tracking-wide`}>Loading your library...</p>
        </div>
      </div>
    );
  }

  if (error && !books.length) {
    return (
      <div className="flex items-center justify-center h-64 px-4">
        <div className="text-center max-w-md mx-auto">
          <div className="p-3 bg-red-500/10 rounded-full inline-block mb-4 border border-red-500/30">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </div>
          <p className="mb-3 text-lg font-semibold text-red-400">Error loading books</p>
          <p className={`${theme.text.secondary} mb-4`}>{error}</p>
          <p className="text-sm text-gray-400 mb-4">
            Please check if the books directory is accessible and contains valid PDF files.
          </p>
          <motion.button 
            className="px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-700 text-white rounded-xl shadow-lg border border-blue-500/30 relative overflow-hidden group"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={() => window.location.reload()}
          >
            <div className="absolute inset-0 bg-gradient-to-r from-blue-400/20 to-indigo-400/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
            <span className="font-medium">Try Again</span>
          </motion.button>
        </div>
      </div>
    );
  }

  if (filteredBooks.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-64 px-4">
        <div className="p-3 bg-blue-500/10 rounded-full inline-block mb-4 border border-blue-500/30">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
        </div>
        <p className={`text-lg font-semibold ${theme.text.primary} mb-2`}>
          {books.length > 0 
            ? 'No books match your search criteria'
            : 'Your library is empty'}
        </p>
        <p className={`${theme.text.secondary} text-center max-w-sm`}>
          {books.length > 0 
            ? 'Try adjusting your search terms or category filters to find what you\'re looking for.'
            : 'Add some PDF books to your library to get started with your study materials.'}
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Error notification */}
      <AnimatePresence>
        {error && (
          <motion.div 
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="mb-4 p-4 bg-gradient-to-r from-red-500/10 to-orange-500/10 border border-red-500/30 text-red-400 rounded-xl shadow-lg relative overflow-hidden"
          >
            <div className="absolute inset-0 bg-red-500/5 -z-10"></div>
            <div className="flex items-start">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-red-400 mt-0.5 mr-2 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <p>{error}</p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      
      {/* Category chips */}
      {categories.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-5 pb-4 border-b border-gray-700/30">
          <motion.button
            className={`px-4 py-2 rounded-xl text-sm font-medium transition-all duration-300 ${
              !categoryFilter 
                ? 'bg-gradient-to-r from-blue-600 to-indigo-700 text-white shadow-lg border border-blue-500/30' 
                : 'bg-gray-800/50 text-gray-300 shadow border border-gray-700/30 hover:bg-gray-700/50'
            }`}
            whileHover={{ scale: 1.03 }}
            whileTap={{ scale: 0.97 }}
            onClick={() => onSelectBook && onSelectBook({ category: null })}
          >
            All Books
          </motion.button>
          
          {categories.map(category => (
            <motion.button
              key={category}
              className={`px-4 py-2 rounded-xl text-sm font-medium transition-all duration-300 ${
                categoryFilter === category 
                  ? 'bg-gradient-to-r from-blue-600 to-indigo-700 text-white shadow-lg border border-blue-500/30' 
                  : 'bg-gray-800/50 text-gray-300 shadow border border-gray-700/30 hover:bg-gray-700/50'
              }`}
              whileHover={{ scale: 1.03 }}
              whileTap={{ scale: 0.97 }}
              onClick={() => onSelectBook && onSelectBook({ category })}
            >
              {category}
            </motion.button>
          ))}
        </div>
      )}
      
      {/* Books list */}
      <div className="overflow-y-auto max-h-[500px] pr-3 space-y-1.5 scrollbar-thin scrollbar-track-gray-800/30">
        {filteredBooks.map((book, index) => (
          <motion.div
            key={book.id || index}
            custom={index}
            variants={itemVariants}
            initial="hidden"
            animate="visible"
            layout
          >
            <PDFThumbnail
              pdfPath={book.path}
              title={book.title}
              author={book.author}
              category={book.category}
              progress={book.progress || 0}
              onClick={() => handleBookClick(book)}
            />
          </motion.div>
        ))}
      </div>
      
      {/* Book count indicator */}
      <div className="pt-3 mt-3 border-t border-gray-700/30 flex justify-between items-center">
        <div className="flex items-center">
          <div className="p-1.5 rounded-full bg-blue-500/10 inline-block">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
            </svg>
          </div>
          <span className="text-sm font-medium text-blue-400 ml-2">{filteredBooks.length} book{filteredBooks.length !== 1 ? 's' : ''}</span>
        </div>
        
        {filteredBooks.length > 0 && searchQuery && (
          <motion.button
            className="text-sm text-gray-400 hover:text-gray-300 flex items-center"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={() => onSelectBook && onSelectBook({ category: null })}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
            Clear filters
          </motion.button>
        )}
      </div>
    </div>
  );
};

export default BookListWithThumbnails; 