import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';

const BookPageFlip = ({ pages = [] }) => {
  const { theme } = useTheme();
  const [currentPage, setCurrentPage] = useState(0);
  const [direction, setDirection] = useState(null);
  const [isFlipping, setIsFlipping] = useState(false);
  
  // Sample pages for demo if none provided
  const demoPages = [
    {
      id: 1,
      title: "Introduction to Study Techniques",
      content: "Effective studying starts with the right approach. The techniques outlined in this book will help you optimize your learning process and maximize retention.",
      image: "https://via.placeholder.com/600x350/3B82F6/FFFFFF?text=Introduction"
    },
    {
      id: 2,
      title: "Active Recall",
      content: "Active recall is the practice of actively stimulating memory during the learning process. It's one of the most effective techniques for moving information from short-term to long-term memory.",
      image: "https://via.placeholder.com/600x350/F59E0B/FFFFFF?text=Active+Recall"
    },
    {
      id: 3,
      title: "Spaced Repetition",
      content: "Spaced repetition involves reviewing information at increasing intervals. This technique leverages the psychological spacing effect, which demonstrates that information is more effectively recalled when reviewed over time.",
      image: "https://via.placeholder.com/600x350/10B981/FFFFFF?text=Spaced+Repetition"
    },
    {
      id: 4,
      title: "Note-Taking Systems",
      content: "Effective note-taking is crucial for information retention. Systems like Cornell Notes, Mind Mapping, and the Outline Method each offer unique advantages depending on the subject matter and your learning style.",
      image: "https://via.placeholder.com/600x350/8B5CF6/FFFFFF?text=Note-Taking"
    }
  ];
  
  const bookPages = pages.length > 0 ? pages : demoPages;
  const totalPages = bookPages.length;
  
  const pageVariants = {
    enter: (direction) => {
      return {
        x: direction > 0 ? 1000 : -1000,
        opacity: 0,
        rotateY: direction > 0 ? -45 : 45,
        boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
      };
    },
    center: {
      zIndex: 1,
      x: 0,
      opacity: 1,
      rotateY: 0,
      boxShadow: "0px 10px 20px rgba(0, 0, 0, 0.2)"
    },
    exit: (direction) => {
      return {
        zIndex: 0,
        x: direction < 0 ? 1000 : -1000,
        opacity: 0,
        rotateY: direction < 0 ? -45 : 45,
        boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
      };
    }
  };

  const paginate = (newDirection) => {
    if (isFlipping) return;
    
    setIsFlipping(true);
    setDirection(newDirection);
    
    if (newDirection > 0) {
      setCurrentPage((prevPage) => (prevPage + 1) % totalPages);
    } else {
      setCurrentPage((prevPage) => (prevPage - 1 + totalPages) % totalPages);
    }
    
    // Reset flipping state after animation completes
    setTimeout(() => {
      setIsFlipping(false);
    }, 500); // Match this with the animation duration
  };

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'ArrowRight') {
        paginate(1);
      } else if (e.key === 'ArrowLeft') {
        paginate(-1);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isFlipping]);

  return (
    <div className="relative">
      {/* Book container */}
      <div className="relative perspective-1000 w-full h-[500px] overflow-hidden rounded-lg">
        <AnimatePresence initial={false} custom={direction}>
          <motion.div
            key={currentPage}
            custom={direction}
            variants={pageVariants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{
              x: { type: "spring", stiffness: 300, damping: 30 },
              opacity: { duration: 0.3 },
              rotateY: { duration: 0.5 }
            }}
            className={`absolute w-full h-full ${theme.card} flex flex-col items-center rounded-lg overflow-hidden`}
            style={{ transformStyle: "preserve-3d", backfaceVisibility: "hidden" }}
          >
            {/* Page content */}
            <div className="h-1/2 w-full relative">
              <img 
                src={bookPages[currentPage].image} 
                alt={bookPages[currentPage].title}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent flex items-end">
                <h2 className="text-white text-2xl font-bold p-4">
                  {bookPages[currentPage].title}
                </h2>
              </div>
            </div>
            
            <div className="p-6 flex-grow overflow-y-auto w-full">
              <p className={`text-base ${theme.text.primary}`}>
                {bookPages[currentPage].content}
              </p>
            </div>
            
            {/* Page corner fold effect */}
            <div className="absolute top-0 right-0 w-16 h-16 bg-gradient-to-bl from-gray-100 to-transparent opacity-30 transform origin-top-right -rotate-6"></div>
          </motion.div>
        </AnimatePresence>
      </div>
      
      {/* Navigation controls */}
      <div className="absolute bottom-4 left-0 right-0 flex justify-between px-4">
        <motion.button
          className={`w-10 h-10 rounded-full bg-blue-500 text-white flex items-center justify-center ${currentPage === 0 ? 'opacity-50 cursor-not-allowed' : 'hover:bg-blue-600'}`}
          whileHover={currentPage !== 0 ? { scale: 1.1 } : {}}
          whileTap={currentPage !== 0 ? { scale: 0.9 } : {}}
          onClick={() => currentPage !== 0 && paginate(-1)}
          disabled={currentPage === 0}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
        </motion.button>
        
        <div className={`${theme.text.secondary} bg-black/40 px-3 py-1 rounded-full backdrop-blur-sm`}>
          Page {currentPage + 1} of {totalPages}
        </div>
        
        <motion.button
          className={`w-10 h-10 rounded-full bg-blue-500 text-white flex items-center justify-center ${currentPage === totalPages - 1 ? 'opacity-50 cursor-not-allowed' : 'hover:bg-blue-600'}`}
          whileHover={currentPage !== totalPages - 1 ? { scale: 1.1 } : {}}
          whileTap={currentPage !== totalPages - 1 ? { scale: 0.9 } : {}}
          onClick={() => currentPage !== totalPages - 1 && paginate(1)}
          disabled={currentPage === totalPages - 1}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
        </motion.button>
      </div>
      
      {/* Page-turning gesture indicators */}
      <div
        className="absolute left-0 top-0 h-full w-1/3 cursor-pointer z-10 flex items-center justify-start opacity-0 hover:opacity-100 transition-opacity"
        onClick={() => currentPage !== 0 && paginate(-1)}
      >
        {currentPage !== 0 && (
          <div className="bg-black/20 h-16 w-8 rounded-r-full flex items-center justify-center backdrop-blur-sm">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </div>
        )}
      </div>
      
      <div
        className="absolute right-0 top-0 h-full w-1/3 cursor-pointer z-10 flex items-center justify-end opacity-0 hover:opacity-100 transition-opacity"
        onClick={() => currentPage !== totalPages - 1 && paginate(1)}
      >
        {currentPage !== totalPages - 1 && (
          <div className="bg-black/20 h-16 w-8 rounded-l-full flex items-center justify-center backdrop-blur-sm">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </div>
        )}
      </div>
    </div>
  );
};

export default BookPageFlip; 