import React, { useState, useEffect, useRef } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import { motion } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';

// Set up PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

// Placeholder images for different categories
const CATEGORY_PLACEHOLDERS = {
  'Textbook': 'https://via.placeholder.com/150/3B82F6/FFFFFF?text=Textbook',
  'Notes': 'https://via.placeholder.com/150/10B981/FFFFFF?text=Notes',
  'Research': 'https://via.placeholder.com/150/8B5CF6/FFFFFF?text=Research',
  'Reference': 'https://via.placeholder.com/150/F59E0B/FFFFFF?text=Reference',
  'Test': 'https://via.placeholder.com/150/3B82F6/FFFFFF?text=Test',
  'Academic': 'https://via.placeholder.com/150/8B5CF6/FFFFFF?text=Academic',
  'Humor': 'https://via.placeholder.com/150/F59E0B/FFFFFF?text=Humor',
  'Comics': 'https://via.placeholder.com/150/EC4899/FFFFFF?text=Comics',
  'default': 'https://via.placeholder.com/150/6B7280/FFFFFF?text=Book'
};

const PDFThumbnail = ({ pdfPath, title, author, progress = 0, onClick, category }) => {
  const { theme } = useTheme();
  const [thumbnailUrl, setThumbnailUrl] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [retries, setRetries] = useState(0);
  const canvasRef = useRef(null);
  const maxRetries = 2;

  // Get placeholder based on category
  const getPlaceholder = () => {
    if (!category) return CATEGORY_PLACEHOLDERS.default;
    return CATEGORY_PLACEHOLDERS[category] || CATEGORY_PLACEHOLDERS.default;
  };

  useEffect(() => {
    let isMounted = true;
    let loadingTask = null;

    async function loadPDF() {
      if (retries > maxRetries) {
        setError("Maximum retries exceeded");
        setIsLoading(false);
        setThumbnailUrl(getPlaceholder());
        return;
      }

      try {
        if (!pdfPath) {
          setError("No PDF path provided");
          setIsLoading(false);
          setThumbnailUrl(getPlaceholder());
          return;
        }

        setIsLoading(true);
        setError(null);
        
        // First check if the PDF exists
        try {
          const response = await fetch(pdfPath, { method: 'HEAD' });
          if (!response.ok) {
            throw new Error(`PDF not found: ${pdfPath}`);
          }
        } catch (err) {
          console.error('PDF not accessible:', err);
          setError("PDF not accessible");
          setIsLoading(false);
          setThumbnailUrl(getPlaceholder());
          return;
        }
        
        // Get PDF document
        loadingTask = pdfjsLib.getDocument({
          url: pdfPath,
          cMapUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@2.16.105/cmaps/',
          cMapPacked: true
        });
        
        const pdf = await loadingTask.promise;
        
        if (!isMounted) return;
        
        // Get the first page
        const page = await pdf.getPage(1);
        
        // Prepare canvas for rendering
        const canvas = canvasRef.current;
        if (!canvas) {
          setThumbnailUrl(getPlaceholder());
          setIsLoading(false);
          return;
        }
        
        // Calculate viewport with higher scale for better quality
        const viewport = page.getViewport({ scale: 0.6 });
        canvas.height = viewport.height;
        canvas.width = viewport.width;
        
        // Render the page
        const renderContext = {
          canvasContext: canvas.getContext('2d'),
          viewport: viewport
        };
        
        await page.render(renderContext).promise;
        
        // Convert canvas to image URL with better quality
        const thumbnailUrl = canvas.toDataURL('image/jpeg', 0.9);
        
        if (isMounted) {
          setThumbnailUrl(thumbnailUrl);
          setIsLoading(false);
        }
      } catch (err) {
        console.error('Error loading PDF:', err);
        
        if (isMounted) {
          // Retry with exponential backoff
          if (retries < maxRetries) {
            const backoffTime = Math.pow(2, retries) * 500;
            setTimeout(() => {
              setRetries(prev => prev + 1);
            }, backoffTime);
          } else {
            setError(`Failed to load PDF thumbnail`);
            setThumbnailUrl(getPlaceholder());
            setIsLoading(false);
          }
        }
      }
    }

    loadPDF();

    return () => {
      isMounted = false;
      if (loadingTask) {
        loadingTask.destroy().catch(err => console.error('Error destroying PDF task:', err));
      }
    };
  }, [pdfPath, retries, category]);

  // Calculate progress color based on percentage
  const getProgressColor = () => {
    if (progress < 30) return 'bg-gradient-to-r from-blue-500 to-blue-400';
    if (progress < 70) return 'bg-gradient-to-r from-blue-500 to-indigo-500';
    return 'bg-gradient-to-r from-blue-600 to-purple-600';
  };

  return (
    <motion.div 
      className={`flex items-center p-4 md:p-4 rounded-xl transition cursor-pointer relative overflow-hidden group touch-manipulation`}
      whileHover={{ x: 4, backgroundColor: theme.isDark ? 'rgba(55, 65, 81, 0.3)' : 'rgba(55, 65, 81, 0.15)' }}
      whileTap={{ scale: 0.98 }}
      onClick={onClick}
    >
      {/* Enhanced touch feedback */}
      <div className="absolute inset-0 bg-gradient-to-r from-blue-500/5 to-purple-600/5 opacity-0 group-hover:opacity-100 active:opacity-100 transition-opacity duration-300 -z-10"></div>
      <div className="absolute top-0 left-0 h-full w-1 bg-gradient-to-b from-blue-500 to-purple-600 opacity-0 group-hover:opacity-80 active:opacity-80 transition-opacity duration-300 rounded-l-xl"></div>
      
      {/* Book thumbnail section - Larger for better touch targets */}
      <div className="h-20 w-16 md:w-14 rounded-lg mr-4 overflow-hidden relative shadow-xl group-hover:shadow-blue-500/20 transition-all duration-300 border border-gray-700/30">
        {isLoading ? (
          <div className="w-full h-full flex items-center justify-center bg-gray-800 relative">
            <div className="w-8 h-8 relative">
              <div className="absolute inset-0 rounded-full border-2 border-blue-500/30 opacity-75"></div>
              <div className="absolute inset-0 rounded-full border-2 border-transparent border-t-blue-500 animate-spin"></div>
            </div>
            <div className="absolute inset-0 bg-gradient-to-br from-blue-500/10 to-purple-600/10 -z-10"></div>
          </div>
        ) : error ? (
          <div className="w-full h-full flex items-center justify-center bg-gray-800 relative">
            <img 
              src={thumbnailUrl || getPlaceholder()} 
              alt={title} 
              className="w-full h-full object-cover opacity-80"
            />
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="p-1 rounded-full bg-red-500/20">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v4m0 2v.01M12 15a1 1 0 110 2 1 1 0 010-2z" />
                </svg>
              </div>
            </div>
          </div>
        ) : (
          <>
            <canvas ref={canvasRef} className="hidden" />
            <div className="relative h-full w-full group">
              <div className="absolute -inset-0.5 bg-gradient-to-r from-blue-500/20 to-purple-600/20 rounded-lg blur opacity-0 group-hover:opacity-100 active:opacity-100 transition duration-500 group-hover:duration-200 z-0"></div>
              <img 
                src={thumbnailUrl || getPlaceholder()} 
                alt={title} 
                className="w-full h-full object-cover relative z-10"
                onError={() => {
                  setError("Failed to load image");
                  setThumbnailUrl(getPlaceholder());
                }}
              />
              {/* Overlay gradient for better text visibility */}
              <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/30 to-black/10 z-20"></div>
            </div>
            
            {/* Corner fold effect */}
            <div className="absolute top-0 right-0 w-4 h-4 bg-gradient-to-bl from-white/30 to-transparent opacity-40 transform origin-top-right -rotate-6 pointer-events-none z-30"></div>
            
            {/* Progress indicator circle on top */}
            <div className="absolute top-1 right-1 flex items-center justify-center z-30">
              <svg className="w-7 h-7 md:w-6 md:h-6" viewBox="0 0 36 36">
                <path
                  d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
                  fill="none"
                  stroke="rgba(30, 41, 59, 0.4)"
                  strokeWidth="4"
                  strokeLinecap="round"
                />
                <path
                  d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
                  fill="none"
                  stroke="url(#gradient)"
                  strokeWidth="4"
                  strokeLinecap="round"
                  strokeDasharray={`${progress}, 100`}
                />
                <defs>
                  <linearGradient id="gradient" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#3B82F6" />
                    <stop offset="100%" stopColor="#8B5CF6" />
                  </linearGradient>
                </defs>
                {progress > 0 && (
                  <text x="18" y="20.35" className="text-[10px] font-medium" textAnchor="middle" fill="white">
                    {progress}%
                  </text>
                )}
              </svg>
            </div>
          </>
        )}
      </div>
      
      {/* Book details section - Improved visibility and touch areas */}
      <div className="flex-grow pr-2">
        <h3 className={`font-semibold truncate text-base ${theme.text.primary} group-hover:text-blue-400 group-active:text-blue-400 transition-colors duration-300`}>{title}</h3>
        <p className={`text-sm truncate ${theme.text.secondary} mb-1.5`}>{author}</p>
        
        {category && (
          <span className="inline-flex items-center px-2.5 py-0.5 bg-gradient-to-r from-blue-500/10 to-indigo-500/10 text-blue-400 text-xs rounded-full mr-2 border border-blue-500/20">
            {category}
          </span>
        )}
        
        <div className="flex items-center mt-2">
          <div className="w-full h-2 md:h-1.5 bg-gray-800/60 rounded-full mr-2 overflow-hidden">
            <div 
              className={`h-full rounded-full ${getProgressColor()}`}
              style={{ width: `${progress}%` }}
            ></div>
          </div>
        </div>
      </div>
      
      {/* Right arrow indicator - Larger for better touch */}
      <div className="opacity-0 group-hover:opacity-100 group-active:opacity-100 transition-opacity">
        <div className="p-2 md:p-1.5 rounded-full bg-blue-500/10 group-hover:bg-blue-500/20 transition-colors duration-300">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 md:h-4 md:w-4 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
        </div>
      </div>
    </motion.div>
  );
};

export default PDFThumbnail; 