import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';
import BookPageFlip from '../components/BookPageFlip';
import BookListWithThumbnails from '../components/BookListWithThumbnails';
import PDFViewer from '../components/PDFViewer';
import { useSwipeable } from 'react-swipeable';

const Books = ({ pages }) => {
  const { theme } = useTheme();
  const [searchQuery, setSearchQuery] = useState('');
  const [uploadModalOpen, setUploadModalOpen] = useState(false);
  const [selectedBook, setSelectedBook] = useState(null);
  const [viewMode, setViewMode] = useState('reader'); // 'reader' or 'pdf'
  const [categoryFilter, setCategoryFilter] = useState(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadForm, setUploadForm] = useState({
    title: '',
    author: '',
    category: '',
    description: ''
  });
  
  // Simple page transition variant
  const pageVariants = {
    initial: { opacity: 0 },
    animate: { opacity: 1, transition: { duration: 0.5 } },
    exit: { opacity: 0, transition: { duration: 0.3 } }
  };
  
  // Enable keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Escape key to return to reader
      if (e.key === 'Escape' && viewMode === 'pdf') {
        handleBackToReader();
      }
    };
    
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [viewMode]);
  
  const handleBookSelect = (book) => {
    // Don't change view mode if it's just a category selection
    if (book.category !== undefined && !book.path && !book.fileUrl) {
      setCategoryFilter(book.category);
      return;
    }
    
    setSelectedBook(book);
    setViewMode('pdf');
  };
  
  const handleBackToReader = () => {
    setViewMode('reader');
    setSelectedBook(null);
  };
  
  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setSelectedFile(file);
      
      // Auto-fill title from filename
      const fileNameWithoutExt = file.name.replace(/\.[^/.]+$/, "");
      setUploadForm(prev => ({
        ...prev,
        title: fileNameWithoutExt
      }));
    }
  };
  
  const handleUploadFormChange = (e) => {
    const { name, value } = e.target;
    setUploadForm(prev => ({
      ...prev,
      [name]: value
    }));
  };
  
  const handleUploadSubmit = (e) => {
    e.preventDefault();
    // In a real app, you would upload the file and form data to a server
    
    // Create a new "book" object
    const newBook = {
      id: Date.now(),
      title: uploadForm.title,
      author: uploadForm.author || 'Unknown',
      category: uploadForm.category || 'Uncategorized',
      description: uploadForm.description,
      fileUrl: selectedFile ? URL.createObjectURL(selectedFile) : null,
      thumbnail: null // Would normally be generated by the server
    };
    
    // Close modal and reset form
    setUploadModalOpen(false);
    setUploadForm({
      title: '',
      author: '',
      category: '',
      description: ''
    });
    setSelectedFile(null);
    
    // For demo purposes, you could add it to a state of books
    console.log('New book would be uploaded:', newBook);
    // Add notification logic here
  };
  
  // Swipe handlers for mobile
  const swipeHandlers = useSwipeable({
    onSwipedRight: () => {
      if (viewMode === 'pdf') {
        handleBackToReader();
      }
    },
    preventDefaultTouchmoveEvent: true,
    trackMouse: true
  });
  
  return (
    <motion.div 
      className="px-4 pb-8"
      variants={pageVariants}
      initial="initial"
      animate="animate"
      exit="exit"
      {...swipeHandlers}
    >
      {viewMode === 'reader' ? (
        <>
          <div className="mb-6 text-center">
            <h1 className={`text-4xl font-bold ${theme.text.primary}`}>
              Book Library
            </h1>
            <p className={`text-lg mt-2 ${theme.text.secondary}`}>
              Explore your study materials and reference books
            </p>
          </div>
          
          <div className="flex flex-col md:flex-row gap-8 items-start">
            <div className="w-full md:w-3/5">
              <BookPageFlip pages={pages} />
            </div>
            
            <div className="w-full md:w-2/5">
              <div className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg mb-6`}>
                <h2 className={`text-xl font-semibold mb-4 ${theme.text.primary}`}>My Library</h2>
                
                <div className="mb-4">
                  <input
                    type="text"
                    placeholder="Search books..."
                    className={`w-full px-4 py-2 rounded-lg bg-gray-800 bg-opacity-50 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500`}
                    value={searchQuery}
                    onChange={e => setSearchQuery(e.target.value)}
                  />
                </div>
                
                <BookListWithThumbnails 
                  searchQuery={searchQuery}
                  categoryFilter={categoryFilter}
                  onSelectBook={handleBookSelect} 
                />
                
                <button
                  className={`mt-4 w-full py-2 px-4 rounded-lg bg-blue-600 hover:bg-blue-700 text-white font-medium transition-colors`}
                  onClick={() => setUploadModalOpen(true)}
                >
                  + Add New Book
                </button>
              </div>
            </div>
          </div>
          
          {/* Upload Modal */}
          {uploadModalOpen && (
            <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 px-4">
              <div className={`${theme.card} rounded-xl shadow-2xl p-6 max-w-lg w-full`}>
                <h2 className={`text-xl font-semibold mb-4 ${theme.text.primary}`}>Upload New Book</h2>
                
                <form onSubmit={handleUploadSubmit}>
                  <div className="space-y-4">
                    <div>
                      <label className={`block mb-1 ${theme.text.secondary}`}>Book File (PDF)</label>
                      <input 
                        type="file" 
                        accept=".pdf"
                        onChange={handleFileChange}
                        className="w-full"
                      />
                    </div>
                    
                    <div>
                      <label className={`block mb-1 ${theme.text.secondary}`}>Title</label>
                      <input 
                        type="text"
                        name="title"
                        value={uploadForm.title}
                        onChange={handleUploadFormChange}
                        className={`w-full px-3 py-2 rounded-lg bg-gray-800 bg-opacity-50 text-white focus:outline-none focus:ring-2 focus:ring-blue-500`}
                        required
                      />
                    </div>
                    
                    <div>
                      <label className={`block mb-1 ${theme.text.secondary}`}>Author</label>
                      <input 
                        type="text"
                        name="author"
                        value={uploadForm.author}
                        onChange={handleUploadFormChange}
                        className={`w-full px-3 py-2 rounded-lg bg-gray-800 bg-opacity-50 text-white focus:outline-none focus:ring-2 focus:ring-blue-500`}
                      />
                    </div>
                    
                    <div>
                      <label className={`block mb-1 ${theme.text.secondary}`}>Category</label>
                      <select
                        name="category"
                        value={uploadForm.category}
                        onChange={handleUploadFormChange}
                        className={`w-full px-3 py-2 rounded-lg bg-gray-800 bg-opacity-50 text-white focus:outline-none focus:ring-2 focus:ring-blue-500`}
                      >
                        <option value="">Select a category</option>
                        <option value="textbook">Textbook</option>
                        <option value="notes">Notes</option>
                        <option value="research">Research Paper</option>
                        <option value="reference">Reference</option>
                      </select>
                    </div>
                    
                    <div>
                      <label className={`block mb-1 ${theme.text.secondary}`}>Description</label>
                      <textarea
                        name="description"
                        value={uploadForm.description}
                        onChange={handleUploadFormChange}
                        className={`w-full px-3 py-2 rounded-lg bg-gray-800 bg-opacity-50 text-white focus:outline-none focus:ring-2 focus:ring-blue-500`}
                        rows="3"
                      ></textarea>
                    </div>
                  </div>
                  
                  <div className="flex justify-end space-x-3 mt-6">
                    <button
                      type="button"
                      className={`py-2 px-4 rounded-lg ${theme.isDark ? 'bg-gray-700 hover:bg-gray-600' : 'bg-gray-200 hover:bg-gray-300'} font-medium transition-colors`}
                      onClick={() => setUploadModalOpen(false)}
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      className={`py-2 px-4 rounded-lg bg-blue-600 hover:bg-blue-700 text-white font-medium transition-colors`}
                    >
                      Upload
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </>
      ) : (
        <div>
          <div className="flex items-center mb-4">
            <button
              onClick={handleBackToReader}
              className={`flex items-center py-2 px-4 rounded-lg ${theme.isDark ? 'bg-gray-800 hover:bg-gray-700' : 'bg-gray-200 hover:bg-gray-300'} font-medium transition-colors ${theme.text.primary}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
              </svg>
              Back to Library
            </button>
            
            <h2 className={`ml-4 text-xl font-semibold ${theme.text.primary}`}>
              {selectedBook?.title || 'PDF Viewer'}
            </h2>
          </div>
          
          <div className={`p-1 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg overflow-hidden h-[calc(100vh-180px)]`}>
            <PDFViewer 
              pdfPath={selectedBook?.path || selectedBook?.fileUrl} 
              bookTitle={selectedBook?.title}
            />
          </div>
        </div>
      )}
    </motion.div>
  );
};

export default Books; 